Object.assign(View, {
  renderSnakeIconAnimation(canvas) {
    const ctx = canvas.getContext("2d");
    let snake = [{x: 4, y: 2}, {x: 3, y: 2}, {x: 2, y: 2}];
    let food = {x: 8, y: 2};
    let dx = 1;
    let frame = 0;

    const interval = setInterval(() => {
      if (!document.body.contains(canvas)) {
        clearInterval(interval);
        return;
      }
      frame++;
      if (frame % 10 === 0) {
        const head = { x: snake[0].x + dx, y: snake[0].y };
        if (head.x >= 14 || head.x < 0) {
          dx = -dx;
          head.x += dx * 2;
        }
        snake.unshift(head);
        snake.pop();
      }

      ctx.fillStyle = "#090b0a";
      ctx.fillRect(0, 0, canvas.width, canvas.height);

      ctx.strokeStyle = "#2b322d";
      ctx.lineWidth = 0.5;
      for (let x = 0; x < canvas.width; x += 10) {
        ctx.beginPath(); ctx.moveTo(x, 0); ctx.lineTo(x, canvas.height); ctx.stroke();
      }
      for (let y = 0; y < canvas.height; y += 10) {
        ctx.beginPath(); ctx.moveTo(0, y); ctx.lineTo(canvas.width, y); ctx.stroke();
      }

      ctx.fillStyle = "#20ef4f";
      snake.forEach(part => {
        ctx.fillRect(part.x * 4 + 1, part.y * 4 + 1, 8, 8);
      });

      ctx.fillStyle = "#ef2020";
      ctx.fillRect(food.x * 4 + 1, food.y * 4 + 1, 8, 8);
    }, 80);
  }
});

